def estimate(points, x):
    """Return the piecewise linear interpolation of ``points`` at ``x``.

    ``points`` must be a list of (x, y) tuples sorted by x.  The function
    clamps values outside the support to the nearest endpoint.
    """
    if not points:
        raise ValueError("empty points list")
    if not isinstance(x, (int, float)):
        raise ValueError("query must be numeric")
    # Clamp to endpoints
    if x <= points[0][0]:
        return points[0][1]
    if x >= points[-1][0]:
        return points[-1][1]
    # Find the interval containing x
    for i in range(1, len(points)):
        left, right = points[i - 1], points[i]
        if x <= right[0]:
            # Linear interpolation
            dx = right[0] - left[0]
            if dx == 0:
                return left[1]  # Should not happen due to duplicate check
            t = (x - left[0]) / dx
            return left[1] + t * (right[1] - left[1])
    # Should never reach here
    return points[-1][1]

